/**
 * Contract test: `skill-index.json` is what the generator writes today (#279)
 *
 * `SkillSearch.ts` searches the committed index. When a `description:` in a
 * SKILL.md changes and nobody regenerates the index, the search keeps the old
 * triggers and nothing turns red. The Claude mirror has a test like this; the
 * index had none (it was regenerated by hand for #269 and #271).
 *
 * `GenerateSkillIndex.ts --sjekk` builds the index in memory and compares it
 * with the file, apart from `generated`. Run against the real tree, and against
 * a temp tree in both directions, so a `--sjekk` that always says yes fails.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const REPO = join(import.meta.dir, "..");
const GENERATOR = join(REPO, ".opencode", "PAI", "Tools", "GenerateSkillIndex.ts");

function kjør(generator: string, ...args: string[]): { kode: number; feil: string } {
	const r = Bun.spawnSync(["bun", generator, ...args], { stdout: "pipe", stderr: "pipe" });
	return { kode: r.exitCode, feil: r.stderr.toString() };
}

describe.skipIf(!existsSync(GENERATOR))("skill-index.json is fresh (#279)", () => {
	test("the committed index is what the generator writes", () => {
		const r = kjør(GENERATOR, "--sjekk");
		// Red: run `bun .opencode/PAI/Tools/GenerateSkillIndex.ts` and commit the index.
		expect(r.feil).toBe("");
		expect(r.kode).toBe(0);
	});
});

describe("GenerateSkillIndex.ts --sjekk", () => {
	let rot: string;
	let generator: string;
	let skill: string;

	const skillMd = (beskrivelse: string) =>
		`---\nname: Eksempel\ndescription: ${beskrivelse}. USE WHEN eksempel, prøve.\n---\n\n# Eksempel\n`;

	beforeEach(() => {
		rot = mkdtempSync(join(tmpdir(), "pai-skill-index-"));
		const verktøy = join(rot, ".opencode", "PAI", "Tools");
		mkdirSync(verktøy, { recursive: true });
		generator = join(verktøy, "GenerateSkillIndex.ts");
		copyFileSync(GENERATOR, generator);
		skill = join(rot, ".opencode", "skills", "Eksempel", "SKILL.md");
		mkdirSync(join(skill, ".."), { recursive: true });
		writeFileSync(skill, skillMd("Gjør det første"));
		expect(kjør(generator).kode).toBe(0);
	});

	afterEach(() => {
		rmSync(rot, { recursive: true, force: true });
	});

	test("silent and 0 right after generating", () => {
		expect(kjør(generator, "--sjekk")).toEqual({ kode: 0, feil: "" });
	});

	test("a changed description without a new index gives 1 and one line", () => {
		writeFileSync(skill, skillMd("Gjør noe annet"));
		const r = kjør(generator, "--sjekk");
		expect(r.kode).toBe(1);
		expect(r.feil).toContain("skill-index.json is stale");
	});

	test("--sjekk does not write the index", () => {
		writeFileSync(skill, skillMd("Gjør noe annet"));
		kjør(generator, "--sjekk");
		expect(kjør(generator, "--sjekk").kode).toBe(1);
	});
});
